def refs(s):
    nums=[]
    for p in s.replace(' ','').split(','):
        if '–' in p or '-' in p:
            a,b=re.split('[–-]',p);nums.extend(range(int(a),int(b)+1))
        elif p:nums.append(int(p))
    return ' '.join(f'<a class="docref" href="#nref-{n}">[N{n}]</a>' if n<=22 else '<small>Registro histórico del atlas</small>' for n in sorted(set(nums)))

def prose(s):
    s=E(s)
    s=re.sub(r'\[([\d, –-]+)\]',lambda m:refs(m[1]),s)
    return ''.join('<p>'+p+'</p>' for p in s.split('\n\n'))

def simple_table(caption, headings, rows):
    return '<div class="table-wrap" tabindex="0" role="region" aria-label="'+E(caption)+'"><table class="guide-table"><caption>'+E(caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+E(h)+'</th>' for h in headings)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def render_guide(V, ORDER, REFS, URLV, GUIDE, SITE, IMF_BLOCK, NOTES):
    title='Anatomía venosa: nombres, siglas y consensos | IMF'
    desc='Guía de anatomía venosa: nombres en español e inglés, siglas GSV y SSV, epónimos y consenso latinoamericano 2023. Tabla bilingüe y atlas 3D del IMF.'
    topics=[('lectura','Cómo leer los nombres'),('anatomia','Anatomía por sistemas'),('historia','Historia y consensos'),('consenso-2023','Siglas del consenso 2023'),('nomenclatura','Tabla bilingüe'),('diferencias','Cambios y confusiones'),('anatomia-regional','Anatomía en profundidad'),('fichas','Fichas del atlas'),('preguntas','Preguntas frecuentes'),('referencias','Fuentes y referencias')]
    toc='<nav class="guide-toc" aria-label="Contenido de la guía"><strong>En esta guía</strong><ol>'+''.join(f'<li><a href="#{i}">{n}</a></li>' for i,n in topics)+'</ol></nav>'
    def section(i,k,h,body):
        return f'<section class="guide-section" id="{i}" aria-labelledby="h-{i}"><p class="eyebrow">{k}</p><h2 id="h-{i}">{h}</h2>{body}</section>'
    content=section('lectura','01 / Un mismo vaso, varios términos','Cómo leer el nombre de una vena','''
<p class="section-intro">El nombre identifica una estructura. El idioma, la tradición y el objetivo del informe explican por qué puedes encontrar distintas denominaciones para ella.</p>
<div class="guide-cards">
<div class="guide-card"><span class="num">NOMBRE PRINCIPAL · ESPAÑOL</span><h3>Safena mayor</h3><p>Es el nombre utilizado en esta web. <b>Safena magna</b> es una equivalencia válida: no describe otra vena.</p></div>
<div class="guide-card"><span class="num">EQUIVALENTE · INGLÉS</span><h3 lang="en">Great saphenous vein</h3><p>Permite reconocer la misma estructura en publicaciones, mapas e informes internacionales.</p></div>
<div class="guide-card"><span class="num">SIGLA · MAPEO</span><h3>GSV</h3><p>Se forma a partir del nombre inglés. El consenso latinoamericano de 2023 emplea siglas inglesas aunque el texto se lea en español.</p></div>
<div class="guide-card"><span class="num">OTROS NOMBRES · CONTEXTO</span><h3>Magna, interna, larga…</h3><p>Algunos son sinónimos; otros pertenecen al uso histórico. Los conservamos para facilitar la búsqueda y explicamos cuándo pueden confundir.</p></div>
</div><div class="callout"><h3>La regla de esta web</h3><p><b>Nombre en español + equivalentes ingleses e históricos + sigla con fuente.</b> Para superficial y perforante usamos el mapeo latinoamericano de 2023. Para otros territorios indicamos CEAP o una leyenda editorial inglesa, sin atribuirla a ese consenso. Las traducciones españolas son equivalencias docentes.</p>'''+refs('1,2,3,9')+'</div>')
    content+=section('anatomia','02 / Orientación anatómica','Primero la anatomía; después las siglas','''
<p class="section-intro">La fascia muscular, el compartimento safeno y las conexiones entre vasos permiten distinguir los sistemas. La pelvis continúa el drenaje del miembro inferior.</p>
<div class="guide-cards">
<div class="guide-card"><span class="num">SUPERFICIAL</span><h3>Safenas y tributarias</h3><p>Se sitúan por encima de la fascia muscular. Los troncos safenos discurren en un compartimento entre fascia safena y fascia muscular. Una tributaria paralela fuera de él no es automáticamente una duplicación.</p><a href="#sup">Consultar sus fichas →</a></div>
<div class="guide-card"><span class="num">PROFUNDO</span><h3>Ejes y venas musculares</h3><p>Incluye tibiales, fibulares, poplítea, femorales y venas musculares. Las venas soleales y gastrocnemias participan en la bomba de la pantorrilla.</p><a href="#deep">Consultar sus fichas →</a></div>
<div class="guide-card"><span class="num">PERFORANTE</span><h3>Conexiones entre sistemas</h3><p>Atraviesan la fascia muscular y comunican el sistema superficial con el profundo. Una comunicante une venas de un mismo sistema. Una tributaria es un afluente: son relaciones distintas.</p><a href="#perf">Consultar sus fichas →</a></div>
<div class="guide-card"><span class="num">PÉLVICO</span><h3>Colectores y tributarias</h3><p>Las ilíacas enlazan el miembro inferior con el retorno central. Las tributarias glúteas, obturatrices y pudendas internas se relacionan con territorios pélvicos y perineales.</p><a href="#pel">Consultar sus fichas →</a></div>
</div><figure class="flow"><div class="flow-line"><span>Venas profundas del pie</span><b aria-label="continúan hacia">→</b><span>Tibiales y fibulares</span><b aria-label="continúan hacia">→</b><span>Poplítea</span><b aria-label="continúa hacia">→</b><span>Femoral / femoral común</span><b aria-label="continúan hacia">→</b><span>Ilíaca externa</span></div><figcaption>Continuidad profunda simplificada. Existen confluencias, vías musculares y variantes; el esquema no representa un patrón idéntico en todas las personas.</figcaption></figure>
<p>Las válvulas, las conexiones y la contracción muscular cooperan en el retorno venoso. El reservorio plantar profundo y las venas musculares explican por qué la bomba del pie y la de la pantorrilla no pueden reducirse a una única vena. Una variante anatómica tampoco demuestra enfermedad por sí sola.</p>'''+refs('1,3,5,7,12,13'))
    timeline=[('2002','Una base internacional común','Caggiati y colaboradores ordenan la nomenclatura del miembro inferior tras el encuentro de Roma de 2001. Se impulsa un lenguaje descriptivo y compartido.','2'),('2005','Extensiones y precisiones anatómicas','La ampliación incorpora detalles clínicos, territorios pélvicos y precisiones sobre nombres y epónimos.','3'),('2006','La UIP relaciona el nombre con la ecografía','Los documentos de principios y anatomía explican cómo identificar los vasos, las fascias, el compartimento safeno y las perforantes.','4,5'),('2019–2020','Terminología y clasificación tienen funciones distintas','Terminologia Anatomica aporta el repertorio anatómico. CEAP 2020 organiza la descripción de la enfermedad venosa e incluye siglas de localización.','1,8'),('2019–2022','Pelvis, clasificación SVP y guía ESVS','El consenso UIP pélvico, SVP y ESVS amplían el contexto anatómico y clínico; no son una única lista nueva de nombres.','7,18,19'),('2023','Consenso latinoamericano de mapeo venoso','Bottini y colaboradores acuerdan un mapa superficial y perforante que acompaña al informe dúplex. Su tabla VI relaciona siglas inglesas con términos en varios idiomas.','9'),('2024','Actualización específica de la safena anterior','El posicionamiento AVLS/AVF/UIP recomienda anterior saphenous vein, ASV. Es una actualización concreta de la antes accesoria anterior; no reemplaza todo el mapa de 2023.','10,11'),('2024–2026','Leer también la fecha de revisión','El parámetro AIUM denominado revisión 2024 se publicó electrónicamente en 2025 y en el volumen de 2026. Una actualización del examen no equivale a renombrar todas las venas.','21')]
    content+=section('historia','03 / Historia y alcance','Por qué cambian los nombres','<p class="section-intro">Los documentos responden a necesidades diferentes: nombrar la anatomía, reconocerla con ultrasonido, clasificar enfermedad o dibujar un mapa. Una fecha más reciente no sustituye automáticamente todos los términos anteriores.</p><ol class="timeline">'+''.join(f'<li><time>{year}</time><h3>{h}</h3><p>{p} {refs(rr)}</p></li>' for year,h,p,rr in timeline)+'</ol>')
    rows2023=DATA['mapping2023']
    content+=section('consenso-2023','04 / La referencia del mapa','Las siglas inglesas del consenso latinoamericano de 2023','<p>Esta tabla de consulta reúne las equivalencias de la tabla VI en una presentación docente propia. La sigla se mantiene en inglés; el texto puede seguir en español. Se han normalizado tildes y la escritura de las uniones. '+refs('9')+'</p>'+simple_table('Referencia de mapeo: Bottini y colaboradores, 2023 · tabla VI', ['Sigla','Nombre en español','Equivalente inglés'],[(f'<span class="sigla">{ab}</span>',E(es),f'<span lang="en">{E(en)}</span>') for ab,es,en in rows2023])+'''<p class="table-help">En pantallas pequeñas, desliza la tabla horizontalmente. Con teclado, enfoca la tabla y usa las flechas.</p><div class="callout"><h3>AAGSV en 2023; ASV en la actualización de 2024</h3><p>La ficha del atlas conserva <b>AAGSV</b> como referencia del mapeo solicitado. Su apartado de otros nombres incluye <b>ASV</b>, <span lang="en">anterior saphenous vein</span> y AASV, con la explicación del cambio de 2024. Así se pueden leer ambos documentos sin tratar sus siglas como si fueran de la misma edición.</p>'''+refs('9,10,11')+'</div>')

    table_rows=[]
    # Las antiguas siglas españolas siguen encontrándose como antecedentes, sin ocupar el rótulo principal.
    editorial={5:'SGV',6:'IGV',7:'LSaV',10:'IPV',11:'ObV',21:'MCFV',22:'LCFV',33:'MPV / LPV',34:'DPVA',45:'IV (grupo)',47:'PAV',59:'DVA',61:'DDV'}
    for i,(es,en,abbr,old,note,rr) in enumerate(DATA['master'],1):
        primary=[];historic=[];kind='other'
        for line in abbr.split('\n'):
            if '[L]' in line:historic.append('Sigla anterior del atlas: '+line.replace(' [L]',''))
            else:primary.append(line)
        if es=='Vena safena anterior':primary=['ASV [A]','AAGSV [M, 2023]'];old+='; anterior accessory saphenous vein; VSAA';rr='9,10,11'
        if i==45:primary=['IV (grupo) [M]','GV en literatura'];rr='3,5,9,15'
        if 'PV + localización' in abbr:primary=['PV + localización [M]'];rr+=',9'
        if not primary:primary=[editorial.get(i,'Sin sigla fijada aquí')+(' [L]' if i in editorial else '')]
        if '[M' in ' '.join(primary) or 'PV + localización' in abbr:kind='map'
        elif '[C]' in ' '.join(primary):kind='ceap'
        elif '[A]' in ' '.join(primary):kind='update'
        if any('[A]' in a for a in primary):kind='update'+(' map' if any('[M' in a for a in primary) else '')
        olds=(old if old!='—' else '').replace(' [L]','').replace('\n','; ')
        if historic:olds+=('; ' if olds else '')+'; '.join(historic)
        badges=''.join('<span class="sigla">'+E(re.sub(r'\s*\[.*?\]','',a))+'</span>'+('<small>'+('Mapeo 2023' if '[M' in a else 'CEAP 2020' if '[C]' in a else 'Posicionamiento 2024' if '[A]' in a else 'Leyenda inglesa del atlas' if '[L]' in a else '')+'</small>') for a in primary)
        note=re.sub(r'^[A-ZÁÉÍÓÚÑ ]+ · ','',note)
        if i==33:note='Venas profundas plantares mediales y laterales. MPV / LPV es leyenda inglesa del atlas.'
        if i==34:note='Profundo se explicita en el rótulo para distinguirlo de la red superficial.'
        if es=='Vena safena anterior':note='AAGSV en el mapa de 2023; ASV en el posicionamiento AVLS/AVF/UIP de 2024. Se conserva la correspondencia histórica.'
        table_rows.append(f'<tr data-row data-kind="{kind}"><td>{E(es)}<span class="en" lang="en">{E(en)}</span></td><td>{badges}</td><td>{E(olds) or "—"}</td><td>{E(note)}<br>{refs(rr)}</td></tr>')
    content+=section('nomenclatura','05 / Consulta bilingüe','Tabla de nombres, siglas y epónimos','''<p class="section-intro">Busca por nombre español, término inglés, sigla o epónimo. La tabla distingue equivalencias, cambios recomendados y términos que describen estructuras diferentes.</p><div class="mini-legend"><span><b>Mapeo 2023</b> · superficial y perforante</span><span><b>CEAP 2020</b> · localización</span><span><b>2024</b> · safena anterior</span><span><b>Leyenda del atlas</b> · convención editorial</span></div>
<div class="table-tools" id="table-tools" hidden><label for="term-search">Buscar término o sigla<input id="term-search" type="search" placeholder="Ej. GSV, Giacomini, tibial, hipogástrica…" autocomplete="off" aria-controls="nomen-table"></label><label for="term-source">Filtrar por referencia<select id="term-source" aria-controls="nomen-table"><option value="all">Todas las referencias</option><option value="map">Mapeo latinoamericano 2023</option><option value="ceap">CEAP 2020</option><option value="update">Actualización 2024 / ASV</option><option value="other">Otras fuentes y leyendas</option></select></label><button id="term-clear" type="button">Limpiar</button></div>
<p class="results" id="term-count" role="status" aria-live="polite">79 entradas de consulta</p><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla bilingüe completa de nomenclatura venosa"><table class="guide-table" id="nomen-table"><caption>Nombres en español e inglés · equivalencias y diferencias con fuente por fila</caption><thead><tr><th scope="col">Estructura / inglés</th><th scope="col">Sigla y referencia</th><th scope="col">Otros nombres / anteriores</th><th scope="col">Qué conviene distinguir</th></tr></thead><tbody>'''+''.join(table_rows)+'''</tbody></table></div><p id="term-empty" class="table-empty" hidden>No hay coincidencias. Prueba con otra palabra o selecciona todas las referencias.</p><p class="table-help">Las siglas españolas anteriores se conservan para reconocer documentos antiguos. Cuando una fuente no fija una sigla, no se presenta como oficial. La tabla incluye grupos anatómicos y conexiones, además de venas individuales; no todas las entradas están representadas en el modelo 3D.</p>''')

    diffs=[('Magna / mayor; parva / menor','Son equivalencias españolas de GSV y SSV. Interna, externa, larga y corta aparecen en textos históricos. LSV es ambigua en inglés.','1,2,5,9'),('Femoral ≠ superficial','Femoral vein, FV, pertenece al sistema profundo. El nombre histórico superficial femoral vein puede inducir errores y se desaconseja.','2,3,8'),('Poplítea ≠ perforante','POPV identifica la poplítea en CEAP. PV significa perforating vein en el mapa de 2023. La sigla debe leerse con su leyenda.','8,9'),('Tibiales posteriores ≠ sus perforantes','PTV corresponde al eje profundo. Las posterior tibial perforating veins atraviesan la fascia: PV más localización.','3,5,8,9'),('Giacomini ≠ toda extensión craneal','CE SSV designa la extensión craneal de la safena menor. Giacomini describe la conexión hacia el territorio de la safena mayor; IV es el grupo intersafeno.','3,5,9,15'),('PAGSV ≠ arco posterior de pierna','PAGSV del mapa de 2023 corresponde a la accesoria posterior del muslo. El arco posterior de pierna es otra localización. No basta la palabra posterior.','3,5,9'),('Boyd, Cockett y Dodd necesitan localización','Cockett orienta a perforantes tibiales posteriores; Boyd al grupo proximal paratibial. Dodd aparece con alcances diversos en la literatura. Describir región y conexiones evita que el epónimo sea la única referencia.','3,5'),('Pudenda externa ≠ pudenda interna','EPV en 2023 corresponde a external pudendal vein. La pudenda interna pertenece al territorio pélvico y se muestra como IPV, con leyenda editorial explícita.','1,3,9')]
    content+=section('diferencias','06 / Evitar confusiones','Sinónimos, cambios y estructuras distintas','<div class="guide-cards">'+''.join(f'<div class="guide-card"><h3>{E(h)}</h3><p>{E(p)}</p>{refs(rr)}</div>' for h,p,rr in diffs)+'</div>')

    anatomy=''
    for i,(h,parts) in enumerate(DATA['chapters']):
        body=''
        for sh,txt in parts:
            # Eliminar recomendaciones de edición del documento; conservar explicación anatómica pública.
            paragraphs=[p for p in txt.split('\n\n') if not any(x in p for x in ('Actualmente las diez entradas','Una ampliación del atlas debería','En el atlas conviene','En una aplicación docente','En un simulador docente','Antes de una publicación institucional'))]
            body+=f'<h4>{E(sh)}</h4>'+prose('\n\n'.join(paragraphs))
        anatomy+=f'<details class="reading" id="region-{i}"><summary>{E(h)}</summary><div class="reading-body">{body}</div></details>'
    content+=section('anatomia-regional','07 / Lectura por regiones','Anatomía venosa en profundidad','<p class="section-intro">Abre el territorio que quieras estudiar. Cada bloque relaciona los nombres con trayectos, fascias, conexiones y variaciones anatómicas.</p>'+anatomy)

    groups=[]
    for sys,h in [('sup','Venas superficiales'),('deep','Venas profundas'),('perf','Venas perforantes'),('pel','Venas pélvicas')]:
        cards=''
        for v in ORDER:
            if v['sys']!=sys:continue
            cards+=f'''<article class="vein" id="v-{v['id']}"><h3><a href="/{URLV(v)}">{E(v['n'])}</a></h3><p class="latin">{E(v['ta'])}</p><p class="pills"><span class="sigla">{E(v['ab'])}</span></p><p class="alt"><b>Otros nombres e inglés:</b> {E(v['alt'])}</p><p class="nomen-note"><b>{E(v['abSource'])}</b><br>{E(v['abNote'])}</p>'''
            for field,label in [('curso','Trayecto'),('drena','Conexiones y drenaje'),('us','Ecografía'),('clin','Contexto clínico')]:cards+=f'<h4>{label}</h4><p>{E(v[field])}</p>'
            cards+='<p class="vfoot"><span>Fuentes: '+' '.join(f'<a href="#ref-{n}">[{n}]</a>' for n in v['refs'])+f'</span><a href="/{URLV(v)}">Ficha completa →</a><a href="/#v-{v["id"]}">Ver en 3D →</a></p></article>'
        groups.append(f'<details class="reading" id="{sys}"><summary>{h} · {sum(v["sys"]==sys for v in V)} fichas</summary><div class="reading-body">{cards}</div></details>')
    content+=section('fichas','08 / Del texto al modelo','Las 27 fichas del atlas','<p>Consulta el trayecto, las conexiones y la equivalencia bilingüe de cada estructura representada. Las siglas de estas fichas son las mismas que ves en el modelo y el simulador.</p><div class="quick-links">'+''.join(f'<a href="#{i}">{h}</a>' for i,h in [('sup','Superficiales'),('deep','Profundas'),('perf','Perforantes'),('pel','Pélvicas')])+'</div>'+''.join(groups))
    faqs=[('¿Por qué usar siglas inglesas si la web está en español?','Porque la tabla VI del consenso latinoamericano de 2023 utiliza acrónimos ingleses para facilitar el intercambio de mapas. Safena mayor se muestra como GSV y safena menor como SSV; el idioma del nombre desarrollado puede seguir siendo español.'),('¿Safena mayor y safena magna son la misma vena?','Sí. Great saphenous vein, GSV, corresponde a safena mayor o magna. Small saphenous vein, SSV, corresponde a safena menor o parva.'),('¿Todas las siglas de esta web proceden del consenso de 2023?','No. Ese documento trata el mapeo superficial y perforante. El sistema profundo utiliza también siglas de CEAP 2020. Otras estructuras tienen una leyenda editorial inglesa identificada en su ficha.'),('¿AAGSV, AASV y ASV se refieren a venas distintas?','Designan la estructura antes llamada safena accesoria anterior en referencias diferentes. El mapa de 2023 usa AAGSV. El posicionamiento AVLS/AVF/UIP de 2024 recomienda anterior saphenous vein, ASV. Es necesario indicar la fuente y el año.'),('¿Los epónimos están prohibidos?','Los nombres descriptivos facilitan la localización. Los epónimos históricos ayudan a reconocer la literatura previa, pero requieren contexto: región, nivel y conexiones. No todos tienen una equivalencia única con un grupo anatómico.'),('¿Puede usarse una sigla sin escribir el nombre completo?','En un mapa debe existir una leyenda clara. En docencia conviene mostrar también el nombre español y el inglés. Una sigla aislada no identifica siempre la misma estructura en todas las publicaciones.')]
    content+=section('preguntas','09 / Respuestas rápidas','Preguntas frecuentes sobre nomenclatura',''.join(f'<details class="reading"><summary>{E(q)}</summary><div class="reading-body"><p>{E(a)}</p></div></details>' for q,a in faqs))

    newrefs='<ol class="reflist">'+''.join(f'<li id="nref-{r["n"]}" data-label="N{r["n"]}">{E(r["text"])} <a href="{E(r["url"])}" target="_blank" rel="noopener">Consultar fuente ↗</a></li>' for r in DATA['sources'])+'</ol>'
    oldrefs='<ol class="reflist">'+''.join(f'<li id="ref-{r["n"]}" value="{r["n"]}">{E(r["a"])}'+(f' <a href="{E(r["u"])}" target="_blank" rel="noopener">Consultar fuente ↗</a>' if r.get('u') else '')+'</li>' for r in REFS if 'n' in r)+'</ol>'
    content+=section('referencias','10 / Fuentes','Bibliografía y criterio editorial','<p>Revisión narrativa documental orientada a la enseñanza, basada en consensos originales, Terminologia Anatomica y estudios anatómicos. Las referencias <b>N1–N22</b> sustentan la explicación y la tabla; las referencias numéricas acompañan las fichas del atlas.</p><p>Actualización editorial: <time datetime="2026-10-29">29 de octubre de 2026</time>. Esta guía es una síntesis docente del Instituto Mexicano de Flebología. Las equivalencias españolas no se presentan como traducción oficial completa de FIPAT o UIP, y una sigla editorial no constituye una recomendación de esas instituciones.</p><div class="refs"><h3>Fuentes de anatomía, nomenclatura y consensos</h3>'+newrefs+'<h3>Referencias de las fichas y del modelo</h3>'+oldrefs+'<p class="notes">'+E(NOTES)+'</p></div>')

    hero='''<p class="crumbs"><a href="/">Anatomía venosa 3D</a> › Guía anatómica</p><header class="guide-hero"><div><p class="eyebrow">Instituto Mexicano de Flebología · Guía de consulta</p><h1>Anatomía venosa de los miembros inferiores: nombres y nomenclatura</h1><p class="lead">Comprende la anatomía, reconoce sus nombres en español e inglés y compara las siglas de los consensos. Una guía para conectar el atlas, el ultrasonido y la literatura.</p><div class="cta"><a class="btn p" href="#nomenclatura">Consultar la tabla bilingüe</a><a class="btn s" href="/">Explorar el atlas 3D →</a></div><div class="guide-meta"><span>Actualizada · 29 oct 2026</span><span>79 entradas de consulta</span><span>27 fichas del atlas</span></div></div><aside class="name-example" aria-label="Ejemplo de lectura de una ficha"><span class="label">Un vaso · varios modos de reconocerlo</span><h2>Vena safena mayor</h2><div class="english" lang="en">Great saphenous vein</div><span class="name-badge">GSV</span><p>También: safena magna<br><i lang="la">Vena saphena magna</i></p><hr><p><b>Nombre en español. Sigla en inglés.</b><br>Referencia: mapeo latinoamericano de 2023.</p></aside></header>'''
    script='''<script>
(()=>{
 const norm=s=>s.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();
 const rows=[...document.querySelectorAll('[data-row]')].map(el=>({el,text:norm(el.textContent),kind:el.dataset.kind}));
 const search=document.getElementById('term-search'),source=document.getElementById('term-source');
 document.getElementById('table-tools').hidden=false;
 function filter(){let n=0;const q=norm(search.value.trim());rows.forEach(r=>{const show=(!q||r.text.includes(q))&&(source.value==='all'||r.kind.split(' ').includes(source.value));r.el.hidden=!show;if(show)n++});document.getElementById('term-count').textContent=n+' de '+rows.length+' entradas';document.getElementById('term-empty').hidden=n!==0}
 search.addEventListener('input',filter);source.addEventListener('change',filter);document.getElementById('term-clear').addEventListener('click',()=>{search.value='';source.value='all';filter();search.focus()});
 function revealHash(){let el=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(!el)return;let p=el;while(p){if(p.tagName==='DETAILS')p.open=true;p=p.parentElement}requestAnimationFrame(()=>el.scrollIntoView({block:'start'}))}
 addEventListener('hashchange',revealHash);if(location.hash)revealHash();
 if('IntersectionObserver' in window){const links=[...document.querySelectorAll('.guide-toc a')];const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){links.forEach(a=>a.removeAttribute('aria-current'));const a=links.find(a=>a.hash==='#'+e.target.id);if(a)a.setAttribute('aria-current','location')}}),{rootMargin:'-90px 0px -65% 0px'});document.querySelectorAll('.guide-section').forEach(s=>obs.observe(s))}
})();
</script>'''
    main=hero+'<div class="guide-layout">'+toc+'<div class="guide-content">'+content+IMF_BLOCK+'</div></div>'+script
    nodes=[{'@type':'MedicalWebPage','@id':GUIDE+'#page','url':GUIDE,'name':'Anatomía venosa de los miembros inferiores: nombres y nomenclatura','description':desc,'inLanguage':'es-MX','dateModified':'2026-10-29','publisher':{'@id':'https://flebo.mx/#org'},'isPartOf':{'@id':SITE+'#website'},'about':{'@type':'AnatomicalSystem','name':'Sistema venoso del miembro inferior','alternateName':['Lower limb venous anatomy','Nomenclatura venosa','Venas de la pierna']},'audience':{'@type':'MedicalAudience','audienceType':'Clinician'},'citation':[r['url'] for r in DATA['sources']],'hasPart':[{'@type':'WebPage','url':SITE+URLV(v),'name':v['n']} for v in ORDER],'image':SITE+'og-image.png'}, {'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Anatomía venosa 3D','item':SITE},{'@type':'ListItem','position':2,'name':'Guía de anatomía y nomenclatura venosa','item':GUIDE}]}]
    return main,nodes,title,desc
